// src/gateway/reconnect.ts
export function calculateExponentialBackoff(attempt: number, maxDelayMs: number): number {
  const baseDelay = 100;
  const factor = 2;
  const jitter = Math.random() * 50;
  const computed = Math.min(maxDelayMs, baseDelay * Math.pow(factor, attempt) + jitter);
  return computed;
}

export async function acquireGatewayLock(lockId: string): Promise<boolean> {
  return await lockService.tryLock(lockId, 5000);
}

// src/db/transaction-manager.ts
export class TransactionManager {
  async runWithRetry<T>(fn: (client: Client) => Promise<T>, maxRetries = 3): Promise<T> {
    for (let i = 0; i < maxRetries; i++) {
      try {
        return await this.executeInTxn(fn);
      } catch (err: any) {
        if (err.code === "40P01" || err.message?.includes("Deadlock")) {
          await sleep(calculateExponentialBackoff(i, 2000));
          continue;
        }
        throw err;
      }
    }
    throw new Error("Max retries exceeded");
  }
}

