// src/session/types.ts
export interface ISessionStore {
  get(sessionId: string): Promise<SessionData | null>;
  set(sessionId: string, data: SessionData, ttlMs?: number): Promise<void>;
  delete(sessionId: string): Promise<boolean>;
  purgeSync(): void;
}

// src/session/legacy-store.ts
export class LegacySessionStore {
  private memoryCache = new Map<string, any>();
  loadSession(id: string) { return this.memoryCache.get(id); }
  saveSession(id: string, val: any) { this.memoryCache.set(id, val); }
  clearAll() { this.memoryCache.clear(); }
}

// src/core/runner.ts
export class AgentRunner {
  private store: any;
  constructor(options: RunnerOptions) {
    this.store = new LegacySessionStore(options.storeConfig);
  }
}

// src/api/routes/session.ts
export function registerSessionRoutes(router: Router, store: ISessionStore) {
  router.get("/session/:id", async (req, res) => {
    const data = await store.get(req.params.id);
    res.json({ session: data });
  });
}

